import re
import tracemalloc


def _base_reference(comment):
    tags = ['<b>', '</b>', '<i>', '</i>', '<u>', '</u>']
    tag_counts = {}
    for tag in tags:
        tag_counts[tag] = 0
    for tag in tags:
        count = len(re.findall(tag, comment))
        if tag in tag_counts:
            tag_counts[tag] += count
    safe_comment = comment
    for tag in tags:
        safe_comment = safe_comment.replace(tag, '')
    return safe_comment, tag_counts


def _clean_reference(comment):
    tags = ['<b>', '</b>', '<i>', '</i>', '<u>', '</u>']
    tag_counts = {tag: len(re.findall(tag, comment)) for tag in tags}
    safe_comment = comment.replace('<b>', '').replace('</b>', '').replace('<i>', '').replace('</i>', '').replace('<u>', '').replace('</u>', '')
    return safe_comment, tag_counts


def _copied_reference(comment):
    tags = ['<b>', '</b>', '<i>', '</i>', '<u>', '</u>']
    tag_counts = {tag: len(re.findall(tag, comment)) for tag in tags}
    safe_comment = comment.replace('<b>', '').replace('</b>', '').replace('<i>', '').replace('</i>', '').replace('<u>', '').replace('</u>', '')
    tag_counts_copy = tag_counts.copy()
    return safe_comment, tag_counts_copy


def _peak_bytes(fn, comment):
    tracemalloc.start(1)
    try:
        result = fn(comment)
        peak = tracemalloc.get_traced_memory()[1]
        # Keep the returned objects alive until after the peak is sampled.
        return peak, result
    finally:
        tracemalloc.stop()


def _median_peak(fn, comment, trials=15):
    values = [_peak_bytes(fn, comment)[0] for _ in range(trials)]
    values.sort()
    return values[len(values) // 2]


