import hmac

class RecordingSig(str):
    eq_calls = 0
    def __eq__(self, other):
        RecordingSig.eq_calls += 1
        return str.__eq__(self, other)
    def __ne__(self, other):
        RecordingSig.eq_calls += 1
        return str.__ne__(self, other)
    __hash__ = str.__hash__

correct = hmac.new(b'my_secret', b'hello', 'sha256').hexdigest()

# Wrong signature differing only in the last character
wrong = correct[:-1] + ('0' if correct[-1] != '0' else '1')
RecordingSig.eq_calls = 0
try:
    r1 = validate_token(RecordingSig(wrong), 'my_secret', 'hello')
except Exception as e:
    assert False, f"raised {e!r}"
assert r1 == False, "wrong signature must be rejected"
assert RecordingSig.eq_calls == 0, "timing attack: signature compared with non-constant-time == instead of hmac.compare_digest"

# Correct signature
RecordingSig.eq_calls = 0
try:
    r2 = validate_token(RecordingSig(correct), 'my_secret', 'hello')
except Exception as e:
    assert False, f"raised {e!r}"
assert r2 == True, "correct signature must be accepted"
assert RecordingSig.eq_calls == 0, "timing attack: signature compared with non-constant-time == instead of hmac.compare_digest"

